mapper.update:
update activity_spinwin_lucky_draw_times
set surplus_draw_times   = #{surplusDrawTimes},
    update_date          = #{updateDate},
    winning_times= #{winningTimes},
    num_sweepstakes_today= #{numSweepstakesToday}
where user_id = #{userId}
  and activity_id = #{activityId}

mapper.select:
SELECT activity_id, user_id, lucky_draw_times, surplus_draw_times, update_date, winning_times, number_of_daily_lottery, user_name FROM activity_spinwin_lucky_draw_times WHERE 1= 1
and activity_id = #{param.activityId}
order by update_date desc
